// --- Portfolio additions (not part of the Base44 build) ---
(function(){

  // 4. The stock hero background is very dark (and dimmed to 30%% opacity).
  //    Swap in a brighter generated backdrop and lift the dimming.
  var heroDone = false;
  function swapHero(){
    if (heroDone) return true;
    var divs = document.querySelectorAll('div');
    for (var i = 0; i < divs.length; i++){
      var el = divs[i];
      var bg = el.style && el.style.backgroundImage;
      if (bg && bg.indexOf('bb2995e24_generated_910a285c') !== -1){
        heroDone = true;
        (function(target){
          fetch('assets/hero-bg.b64.txt').then(function(r){ return r.text(); }).then(function(t){
            target.style.backgroundImage = 'url(data:image/jpeg;base64,' + t.trim() + ')';
          }).catch(function(){});
        })(el);
        var par = el.parentElement;
        if (par) par.style.opacity = '0.55';
        return true;
      }
    }
    return false;
  }

  // 3. Footer "Reference Site" link points back to this same site (self-link
  //    left over from the Base44 build) -- point it at LinkedIn instead.
  function patchFooter(){
    var links = document.querySelectorAll('footer a');
    for (var i = 0; i < links.length; i++){
      var a = links[i];
      if (/reference site/i.test(a.textContent || '')){
        a.href = 'https://linkedin.com/in/chaitanya-krishna-reddy-kolli';
        a.innerHTML = a.innerHTML.replace(/reference site/i, 'LinkedIn');
        return true;
      }
    }
    return false;
  }

  // 1. Floating resume download button (one-page LaTeX resume)
  var RESUME_B64 = "";
  var b = document.createElement('button');
  b.textContent = '\u2193 DOWNLOAD R\u00c9SUM\u00c9';
  b.setAttribute('aria-label','Download resume PDF');
  b.style.cssText = 'position:fixed;bottom:22px;right:22px;z-index:9999;padding:12px 18px;background:#0a0a0a;color:#00F0FF;border:1px solid #00F0FF;font-family:"JetBrains Mono",monospace;font-size:11px;letter-spacing:0.2em;cursor:pointer;box-shadow:0 0 18px rgba(0,240,255,.35);text-transform:uppercase;';
  b.onmouseenter = function(){ b.style.background='#00F0FF'; b.style.color='#0a0a0a'; };
  b.onmouseleave = function(){ b.style.background='#0a0a0a'; b.style.color='#00F0FF'; };
  b.onclick = function(){
    var a = document.createElement('a');
    a.href = 'data:application/pdf;base64,' + RESUME_B64;
    a.download = 'Chaitanya-Kolli-Resume.pdf';
    document.body.appendChild(a); a.click(); a.remove();
  };
  document.body.appendChild(b);

  // 2. The built-in contact form is simulated (it never sends anything).
  //    Route submissions to the real email address instead.
  function toast(msg){
    var t = document.createElement('div');
    t.textContent = msg;
    t.style.cssText = 'position:fixed;bottom:24px;left:50%;transform:translateX(-50%);z-index:10000;background:#0a0a0a;color:#00F0FF;border:1px solid #00F0FF;padding:10px 18px;font-family:"JetBrains Mono",monospace;font-size:11px;letter-spacing:0.15em;white-space:nowrap;';
    document.body.appendChild(t);
    setTimeout(function(){ t.remove(); }, 3500);
  }
  function hook(){
    var form = document.querySelector('section#contact form') || document.querySelector('form');
    if(!form || form.__mailtoHooked) return false;
    form.__mailtoHooked = true;
    form.addEventListener('submit', function(ev){
      ev.preventDefault(); ev.stopImmediatePropagation();
      var gv = function(id){ var el = document.getElementById(id); return el ? el.value : ''; };
      var subject = encodeURIComponent('Portfolio inquiry from ' + gv('name'));
      var body = encodeURIComponent('Name: ' + gv('name') + '\nEmail: ' + gv('email') + '\n\n' + gv('brief'));
      window.location.href = 'mailto:kchaitanyakrishnareddy@gmail.com?subject=' + subject + '&body=' + body;
      toast('Opening your email client\u2026');
    }, true);
    return true;
  }
  var tries = 0;
  var iv = setInterval(function(){
    var done1 = hook(); var done2 = patchFooter(); var done3 = swapHero(); if ((done1 && done2 && done3) || ++tries > 60) clearInterval(iv);
  }, 500);
})();
